def steps_to_zero(n):
    steps = 0
    # Stop as soon as n hits 0. For n == 0 the body never runs and we return 0.
    while n > 0:
        if n % 2 == 0:
            n //= 2      # even: halve (// keeps it an int)
        else:
            n -= 1       # odd: subtract one, which makes it even
        steps += 1       # n strictly decreased, so the loop is guaranteed to end
    return steps

