    array<int, 26> count{};              // value-initialised to zeros
    for (size_t i = 0; i < s.size(); ++i) {
        ++count[s[i] - 'a'];
        --count[t[i] - 'a'];
    }
    for (int c : count) if (c != 0) return false;
    return true;
}

