        {1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"}, {100, "C"}, {90, "XC"},
        {50, "L"}, {40, "XL"}, {10, "X"}, {9, "IX"}, {5, "V"}, {4, "IV"}, {1, "I"}};
    string out;
    for (const auto& [value, symbol] : table)      // structured bindings (C++17)
        while (num >= value) { out += symbol; num -= value; }
    return out;
}

