long long* product_except_self(long long* nums, int numsSize, int* returnSize) {
    long long* ans = malloc(sizeof(long long) * numsSize);
    ans[0] = 1;
    for (int i = 1; i < numsSize; i++) ans[i] = ans[i - 1] * nums[i - 1];  // left products
