pub fn next_permutation(nums: &mut Vec<i64>) {
    let n = nums.len();
    // Find the pivot using a "start of suffix" index so nothing goes below 0.
    let mut s = n.saturating_sub(1); // suffix nums[s..] is non-increasing
    while s > 0 && nums[s - 1] >= nums[s] {
        s -= 1;
    }
    if s > 0 {
        let i = s - 1; // pivot
        let mut j = n - 1;
        while nums[j] <= nums[i] {
            j -= 1;
        }
        nums.swap(i, j);
    }
    nums[s..].reverse();
}

