        // 1..n - p never underflows because p < n; compare (i-1, i) pairs.
        for i in 1..n - p {
            if nums[i - 1] > nums[i] {
                nums.swap(i - 1, i); // Vec::swap exchanges two slots in place
                swapped = true;
            }
        }
        if !swapped {
            break;
        }
    }
}

