    // Unsettled prefix is nums[0 .. n-p-1]; the tail is already final.
    for var i in 1..n - p {
      if nums[i - 1] > nums[i] {
        var tmp = nums[i - 1]
        nums[i - 1] = nums[i]
        nums[i] = tmp
        swapped = true
      }
    }
    p += 1
  }
