pub fn search_rotated(nums: Vec<i64>, target: i64) -> i64 {
    // Signed bounds so hi = mid - 1 can safely reach -1.
    let (mut lo, mut hi) = (0i64, nums.len() as i64 - 1);
    while lo <= hi {
