pub fn min_eating_speed(piles: Vec<i64>, h: i64) -> i64 {
    let feasible = |k: i64| -> bool {
        let mut hours = 0i64;
        for &p in &piles {
            hours += (p + k - 1) / k;
            if hours > h {
                return false;
            }
        }
        true
    };
    let (mut lo, mut hi) = (1i64, *piles.iter().max().unwrap());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if feasible(mid) { hi = mid; } else { lo = mid + 1; }
    }
    lo
