// Values are within +-10^6, so +-2147483647 work as infinities.
fn medianCut(a, b) {
  var m = len(a)
  var n = len(b)
  var half = (m + n + 1) / 2
  var lo = 0
  var hi = m
  while lo <= hi {
    var i = lo + (hi - lo) / 2
    var j = half - i
    var l1 = -2147483647
    var r1 = 2147483647
    var l2 = -2147483647
    var r2 = 2147483647
    if i > 0 { l1 = a[i - 1] }
    if i < m { r1 = a[i] }
    if j > 0 { l2 = b[j - 1] }
    if j < n { r2 = b[j] }
    if l1 <= r2 and l2 <= r1 {
      var left = l1
      if l2 > left { left = l2 }
      var right = r1
      if r2 < right { right = r2 }
      var total = m + n
      // no % in ESPresso: total is odd when total - (total / 2) * 2 == 1
      if total - (total / 2) * 2 == 1 { return left * 1.0 }
      return (left + right) / 2.0
    }
    if l1 > r2 {
      hi = i - 1
    } else {
      lo = i + 1
    }
  }
  return 0.0
}

fn findMedianSorted(nums1, nums2) {
  if len(nums1) > len(nums2) { return medianCut(nums2, nums1) }
  return medianCut(nums1, nums2)
}

