def is_balanced(root):
    def check(node):
        """Height of `node` if its subtree is balanced, otherwise -1."""
        if node is None:
            return 0
        l = check(node.left)
        if l == -1:            # imbalance below: no point looking further
            return -1
        r = check(node.right)
        if r == -1:
            return -1
        if abs(l - r) > 1:     # this node itself violates the rule
            return -1
        return 1 + max(l, r)

    return check(root) != -1

