    // O(n^2) DP: dp[i] = longest increasing subsequence ending at i.
    let n = nums.len();
    let mut dp = vec![1i64; n];
    for i in 0..n {
        for j in 0..i {
            if nums[j] < nums[i] {
                dp[i] = dp[i].max(dp[j] + 1);
            }
        }
