pub fn can_partition(nums: Vec<i64>) -> bool {
    let total: i64 = nums.iter().sum();
    if total % 2 == 1 {
        return false;
    }
    let target = (total / 2) as usize;
    let mut can = vec![false; target + 1];
    can[0] = true;
    for &x in &nums {
        let x = x as usize;
        // Downward so each number is used at most once.
        for s in (x..=target).rev() {
            if can[s - x] {
                can[s] = true;
            }
        }
    }
    can[target]
}

