long long num_decodings(char* s) {
    int n = strlen(s);
    long long prev2 = 0, prev1 = 1;          /* dp[i-2], dp[i-1]; dp[0] = 1 */
    for (int i = 1; i <= n; i++) {
        long long cur = 0;
        if (s[i - 1] != '0') cur += prev1;   /* single digit 1..9 */
        if (i >= 2) {
            int two = (s[i - 2] - '0') * 10 + (s[i - 1] - '0');
            if (two >= 10 && two <= 26) cur += prev2;   /* two digits 10..26 */
        }
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

