    let cols = matrix[0].len();
    let mut row = vec![0i64; cols + 1];
    let mut best = 0i64;
    for line in &matrix {
        let mut diag = 0i64;
        for c in 1..=cols {
            let up = row[c];
            row[c] = if line[c - 1] == 1 { 1 + up.min(row[c - 1]).min(diag) } else { 0 };
            best = best.max(row[c]);
            diag = up;
        }
    }
    best * best
}

