    a.insert(a.end(), nums.begin(), nums.end());
    a.push_back(1);
    int m = a.size();
    vector<vector<long long>> dp(m, vector<long long>(m, 0));
    // l descending, r ascending: dp[l][k] (same row, smaller r) and dp[k][r] (row below)
    // are both already computed.
    for (int l = m - 3; l >= 0; --l)
        for (int r = l + 2; r < m; ++r)
            for (int k = l + 1; k < r; ++k)
