pub fn reverse_bits(n: i64) -> i64 {
    // Explicit loop on u32; the built-in equivalent is (n as u32).reverse_bits().
    let mut x = n as u32;
    let mut res: u32 = 0;
    for _ in 0..32 {
        res = (res << 1) | (x & 1);
        x >>= 1;
    }
    res as i64   // u32 -> i64 is a zero-extension, never negative
}

