// No bitwise operators in ESPresso: divide by 4 while it divides evenly.
fn isPowerOfFour(n) {
  if n <= 0 { return false }
  var x = n
  while x - (x / 4) * 4 == 0 {   // x mod 4 == 0
    x = x / 4
  }
  return x == 1                   // only 4^k reduces all the way to 1
}

