pub fn missing_number(nums: Vec<i64>) -> i64 {
    // XOR indices 0..n with values; pairs cancel.
    let n = nums.len() as i64;
    nums.iter().enumerate().fold(n, |acc, (i, &x)| acc ^ i as i64 ^ x)
}

