// ESPresso lacks XOR, so use the running-difference form of the sum trick:
// sum over i of ((i + 1) - nums[i]) = n(n+1)/2 - sum(nums) without a big intermediate.
fn missingNumber(nums) {
  var acc = 0
  for var i in 0..len(nums) {
    acc += (i + 1) - nums[i]
  }
  return acc
}

