pub fn get_sum(a: i64, b: i64) -> i64 {
    // u32 shifts discard bits that leave the word; no overflow panic possible.
    let (mut x, mut y) = (a as u32, b as u32);
    while y != 0 {
        let carry = (x & y) << 1;
        x ^= y;
        y = carry;
    }
    x as i32 as i64   // reinterpret as signed 32-bit, then sign-extend
}

