pub fn pascal_row(row_index: i64) -> Vec<i64> {
    let k = row_index as usize;
    let mut row = vec![1i64; k + 1];
    for i in 2..=k {
        for j in (1..i).rev() {      // right to left
            row[j] += row[j - 1];
        }
    }
    row
}

