pub fn mod_pow(base: i64, exponent: i64, modulus: i64) -> i64 {
    // u64 throughout; products of two values < 2^31 fit easily.
    let m = modulus as u64;
    let (mut result, mut b, mut e) = (1 % m, base as u64 % m, exponent as u64);
    while e > 0 {
        if e & 1 == 1 {
            result = result * b % m;
        }
        b = b * b % m;
        e >>= 1;
    }
    result as i64
}

