vector<string> convertExcel(vector<string>& queries) {
    vector<string> out;
    for (const string& q : queries) {
        if (isdigit((unsigned char)q[0])) {
            long long n = stoll(q);
            string s;
            while (n > 0) {
                n--;                         // bijective: digits 1..26 -> 0..25
                s += char('A' + n % 26);
                n /= 26;
            }
            reverse(s.begin(), s.end());
            out.push_back(s);
        } else {
            long long v = 0;
            for (char c : q) v = v * 26 + (c - 'A' + 1);
            out.push_back(to_string(v));
        }
    }
    return out;
}

