const M: u64 = 1_000_000_007;
type Mat = [[u64; 2]; 2];

fn mul(a: &Mat, b: &Mat) -> Mat {
    let mut r = [[0u64; 2]; 2];
    for i in 0..2 {
        for j in 0..2 {
            // two products < 1e18 each; their sum < 2e18 < u64::MAX
            r[i][j] = (a[i][0] * b[0][j] + a[i][1] * b[1][j]) % M;
        }
    }
    r
}

pub fn fib_mod(n: i64) -> i64 {
    let (mut res, mut base): (Mat, Mat) = ([[1, 0], [0, 1]], [[1, 1], [1, 0]]);
    let mut e = n as u64;
    while e > 0 {
        if e & 1 == 1 {
            res = mul(&res, &base);
        }
        base = mul(&base, &base);
        e >>= 1;
    }
    res[0][1] as i64
}

