// Same state machine; `hi` is the output state.
long long schmittEdges(vector<long long>& signal, long long low, long long high) {
    bool hi = false;
    long long edges = 0;
    for (long long v : signal) {
        if (!hi && v >= high) { hi = true; edges++; }
        else if (hi && v <= low) hi = false;
    }
    return edges;
}

