pub fn schmitt_edges(signal: Vec<i64>, low: i64, high: i64) -> i64 {
    let mut hi = false;
    let mut edges = 0;
    for v in signal {
        if !hi && v >= high {
            hi = true;
            edges += 1;
        } else if hi && v <= low {
            hi = false;
        }
    }
    edges
}

