// Binary search on the answer. hi starts at 46340 so mid * mid can never
// exceed 46340^2 = 2147395600 < 2^31: no silent 32-bit wraparound.
fn isqrt(n) {
    var lo = 0
    var hi = 46340
    if n < hi { hi = n }
    while lo < hi {
        var mid = (lo + hi + 1) / 2     // round up so "lo = mid" always makes progress
        if mid * mid <= n {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    return lo
}

refs.cpp:
// Same search, written with the 32-bit-safe comparison mid <= n / mid.
long long isqrt(long long n) {
    long long lo = 0, hi = min(n, 46340LL);
    while (lo < hi) {
        long long mid = (lo + hi + 1) / 2;
        if (mid <= n / mid) lo = mid; else hi = mid - 1;
    }
    return lo;
}

refs.rust:
pub fn isqrt(n: i64) -> i64 {
    let (mut lo, mut hi) = (0i64, n.min(46340));
    while lo < hi {
        let mid = (lo + hi + 1) / 2;
        if mid * mid <= n { lo = mid } else { hi = mid - 1 }
    }
    lo
}

