// Counter-based debouncer, the same logic you'd run in a 1 ms timer interrupt.
fn countPresses(samples, k) {
    var state = 0
    var run = 0
    var presses = 0
    for var i in 0..len(samples) {
        if samples[i] == state {
            run = 0                 // agreement resets the streak
        } else {
            run += 1
            if run == k {           // stable for k ticks: accept the new level
                state = samples[i]
                run = 0
                if state == 1 { presses += 1 }
            }
        }
    }
    return presses
}

refs.cpp:
long long countPresses(vector<long long>& samples, long long k) {
    long long state = 0, run = 0, presses = 0;
    for (long long s : samples) {
        if (s == state) { run = 0; continue; }
        if (++run == k) {
            state = s;
            run = 0;
            presses += state;   // +1 only on a 0 -> 1 flip
        }
    }
    return presses;
}

refs.rust:
pub fn count_presses(samples: Vec<i64>, k: i64) -> i64 {
    let (mut state, mut run, mut presses) = (0, 0, 0);
    for s in samples {
        if s == state {
            run = 0;
        } else {
            run += 1;
            if run == k {
                state = s;
                run = 0;
                presses += state;
            }
        }
    }
    presses
}

