def led_overlap(periods, duties, ticks):
    count = 0
    for t in range(ticks):
        # An LED is on during the first duties[i] ticks of each cycle of periods[i].
        if all(t % p < d for p, d in zip(periods, duties)):
            count += 1
    return count

